<?php
$p='sticky_anchor_sidebar'; $sidebarTitle=get_field("{$p}_sidebar_title"); $anchors=get_field("{$p}_anchors")?:[]; $cta=get_field("{$p}_cta"); $eyebrow=get_field("{$p}_eyebrow"); $title=get_field("{$p}_title"); $content=get_field("{$p}_content"); $image=get_field("{$p}_image"); $settings=get_field("{$p}_section_settings"); $sectionId=inkwell_component_id($block??[],'sticky-anchor-sidebar');
?>
<section id="<?php echo esc_attr($sectionId);?>" class="sticky-anchor-sidebar px-6 <?php echo esc_attr(inkwell_component_section_classes($settings,$p));?>" data-anchor-sidebar><div class="mx-auto grid gap-10 lg:grid-cols-[190px_minmax(0,1fr)] lg:gap-12 <?php echo esc_attr(inkwell_component_container_class($settings,$p));?>"><aside class="lg:sticky lg:top-8 lg:self-start"><?php if($sidebarTitle){?><p class="mb-4 text-xs font-semibold uppercase tracking-[.14em] opacity-60"><?php echo esc_html($sidebarTitle);?></p><?php }?><nav class="flex gap-2 overflow-x-auto border-b border-[#dfe5ee] lg:block lg:border-b-0 lg:border-r" aria-label="<?php echo esc_attr($sidebarTitle?:'On this page');?>"><?php foreach($anchors as $i=>$anchor){$target=sanitize_title($anchor["{$p}_anchor_target"]??'');if(!$target)continue;?><a class="anchor-sidebar-link block whitespace-nowrap border-b-2 px-3 py-2 text-sm lg:border-b-0 lg:border-l-2 <?php echo $i===0?'is-active border-[#0867f2] text-[#0867f2]':'border-transparent opacity-70';?>" href="#<?php echo esc_attr($target);?>" data-anchor-target="<?php echo esc_attr($target);?>"><?php echo esc_html($anchor["{$p}_anchor_label"]??'');?></a><?php }?></nav><?php if($cta){?><div class="mt-6 hidden lg:block"><?php echo inkwell_component_link($cta,'inline-flex rounded bg-[#0867f2] px-5 py-3 text-xs font-semibold text-white');?></div><?php }?></aside><div class="grid gap-10 xl:grid-cols-[minmax(0,1fr)_260px]"><div><?php if($eyebrow){?><p class="mb-4 text-xs font-semibold uppercase tracking-[.14em] opacity-60"><?php echo esc_html($eyebrow);?></p><?php }?><?php if($title){?><h2 class="text-[clamp(34px,4vw,52px)] font-semibold leading-[1.08]"><?php echo esc_html($title);?></h2><?php }?><?php if($content){?><div class="mt-5 leading-7 opacity-75"><?php echo wp_kses_post($content);?></div><?php }?></div><?php if($image){?><div class="min-h-[320px] overflow-hidden bg-[#e9edf3]"><?php echo inkwell_component_image($image,'large','h-full min-h-[320px] w-full object-cover');?></div><?php }?></div></div></section>
